```javascript
function sumDictionaryValues(dict) {
    let total = 0;
    for (let key in dict) {
        if (dict.hasOwnProperty(key)) { // 使用hasOwnProperty确保我们只处理字典自身的属性，而不是原型链上的属性
            total += dict[key];
        }
    }
    return total;
}

// 示例：
const myDict = {'a': 1, 'b': 2, 'c': 3};
console.log(sumDictionaryValues(myDict)); // 输出：6
